"""Independent literal economics and full published-output verification."""
import io, contextlib
_buffer=io.StringIO()
with contextlib.redirect_stdout(_buffer):
    exec(compile('#!/usr/bin/env python3\n"""Independent literal reconstruction. Does not import production model or copy its DPS.\nReads saved output only after reconstructing economic and cash schedules.\n"""\nimport json, pathlib\n# Literal source-based construction economics independently transcribed (bn CNY).\nunits=[(2026,20.35962,.82,.01),(2026,20.35962,.82,.02),(2026,21.1005,.46,.02),\n (2027,21.1005,.46,.10),(2027,20.376,1,.32),(2028,20.376,1,.48),\n (2030,20.69223,1,.30),(2030,20.69223,1,.30),(2030,19.02892,1,.68),\n (2031,19.02892,1,.74),(2029,19.15,.51,.50),(2030,19.15,.51,.58),\n (2030,19.175,.51,.82),(2033,19.175,.51,.90),(2031,21.01624,1,.76),\n (2032,21.01624,1,.84),(2033,18.153,.61,.86),(2034,18.153,.61,.90),\n (2034,20,1,.95),(2035,20,1,.98),(2034,20,1,.98),(2035,20,1,.99)]\n\ndef reconstruct(tariff,normal,r,end_of_old=40,flat_years=10):\n    face=4.8992182; balances=[225-face-25,face,25.]; amort=[(225-face-25)/30,0,25/30]; starts=[1,1,1];ts_loan=[False,False,True]\n    liquid_sub=6.5; liquid_parent=3.678; ret_sub=30.; res_sub=0.\n    ret_parent=30.609456005;res_parent=8.191772221;ar=3.295550588;bridge=0.\n    payments=[];cash=[];taishan=[]\n    tscash=.5;tsret=-4.355*.51;tsreserve=0.;intermediate=0.;interreserve=0.\n    # Independently construct obligations from literal costs and lives, not production schedules.\n    obligations=[]\n    for exit_year in range(flat_years+1,end_of_old+1):\n        amount=(4/(end_of_old-flat_years))*1.055**exit_year\n        deposit=amount/sum(1.02**(exit_year-k) for k in range(1,exit_year+1))\n        obligations.append((1,exit_year,deposit,False,amount))\n    for cod,budget,owner,left in units:\n        start=max(1,cod-2026);end=cod+60-2026;half=cod>=2027\n        amount=budget*owner*.10*1.02**end\n        deposit=amount/sum((.5 if k==start and half else 1)*1.02**(end-k) for k in range(start,end+1))\n        obligations.append((start,end,deposit,half,amount))\n    fund=0.\n    for n in range(1,81):\n        year=2026+n;run=max(0.,min(1.,(end_of_old-n)/(end_of_old-flat_years)))\n        ebit_aftertax=(normal-.4)*run+(.09 if n<=3 else 0)+(.31 if n<=15 else 0)\n        ebit_aftertax-=.60*min(1.,max(0.,(n-1)/8))*run\n        depreciation=8*run; maintenance=4*run;owned_capacity=0;construction=0.\n        opening_debt=sum(balances)\n        taishan_open_debt=sum(b for b,owned in zip(balances,ts_loan) if owned)\n        for cod,budget,owner,left in units:\n            start=max(2027,cod-5); finish=max(2027,cod)\n            if start<=year<=finish:construction+=budget*owner*left/max(1,cod-start+1)\n            age=year-cod\n            utilisation=(.5 if age==0 else 1.) if 0<=age<60 else 0.\n            owned_capacity+=1.2*owner*utilisation\n            d=budget*owner*(.033 if age<30 else .012)*utilisation\n            depreciation+=d;maintenance+=budget*owner*.012*utilisation\n            ebit_aftertax+=(1.2*owner*utilisation*7.15*(tariff-.14)-d)*.75\n        tsoperating_profit=(([.4,.8][n-1] if n<=2 else 1.2)*.51+.50625)*run\n        ebit_aftertax+=tsoperating_profit-1.11825*run\n        decommission=sum(a*(.5 if n==start and half else 1) for start,end,a,half,cost in obligations if start<=n<=end)\n        retirement=sum(cost for start,end,a,half,cost in obligations if n==end)\n        tsfunding=sum(a for start,end,a,half,cost in obligations[:end_of_old-flat_years] if n<=end)*1.785/17.1103056\n        fund=fund*1.02+decommission-retirement\n        borrowing=construction*.8\n        if borrowing:balances.append(borrowing);amort.append(borrowing/30);starts.append(n+1);ts_loan.append(False)\n        repayment=0.;ts_repayment=0.\n        for i in range(len(balances)):\n            pay=min(balances[i],amort[i]) if n>=starts[i] else 0.\n            balances[i]-=pay;repayment+=pay\n            if ts_loan[i]:ts_repayment+=pay\n        interest=max(0.,opening_debt-70*max(0.,1-n/10))*.027\n        if n<=5:interest+=face*([.008,.012,.016,.020,.020][n-1]-.027)\n        tsgross=taishan_open_debt*.027\n        tshield=min(tsgross*.25,max(0,tsoperating_profit)/.75*.25)\n        tsinterest=tsgross-tshield\n        aftertax_interest=interest*.75+min(interest,27.5*max(0.,1-(n-1)/30)*.027)*.25+tsinterest-tsgross*.75\n        tsprofit=tsoperating_profit-tsinterest-tsfunding\n        if n==5:\n            balances[1]=0;balances.append(face*1.04);amort.append(face*1.04/20);starts.append(6);ts_loan.append(False)\n        profit=ebit_aftertax-aftertax_interest-decommission-(face*.04 if n==5 else 0)\n        principal_recovery=(4.7 if n==3 else 0)+(6.5 if n==15 else 0)\n        taishan_flow=tsprofit+.99*run-ts_repayment\n        tscash+=taishan_flow\n        need=max(0,-tscash)\n        if need:tscash+=need;balances.append(need);amort.append(need/15);starts.append(n+1);ts_loan.append(True)\n        liquid_sub+=ebit_aftertax+depreciation-maintenance-decommission+principal_recovery-aftertax_interest-repayment-taishan_flow\n        eligible=max(0,tsprofit-max(0,-tsret));tsret+=tsprofit\n        addition=min(max(0,28.6*.51*.5-tsreserve),eligible*.1)\n        tsreserve+=addition;tsret-=addition\n        tsdiv=min(max(0,tsprofit)*.75,max(0,tsret),max(0,tscash));tsret-=tsdiv;tscash-=tsdiv\n        if n>=12:\n            extra=min(max(0,tscash-.2)/max(1,22-n),max(0,tsret),max(0,tscash))\n            tsret-=extra;tscash-=extra;tsdiv+=extra\n        arriving=intermediate;intermediate=0\n        reserve_add=min(max(0,.009-interreserve),tsdiv*28.5/51*.1)\n        interreserve+=reserve_add;intermediate=tsdiv*38.5/51-reserve_add\n        tsreceipt=tsdiv*12.5/51+arriving\n        capital_back=0;exit_support=0\n        if n==end_of_old:\n            remaining=sum(b for b,owned in zip(balances,ts_loan) if owned)\n            exit_support=max(0,remaining-tscash);tscash+=exit_support-remaining\n            liquid_parent-=exit_support\n            for j in range(len(balances)):\n                if ts_loan[j]:balances[j]=0\n            capital_back=tscash+interreserve;tsreceipt+=capital_back;tscash=interreserve=0\n        other_profit=profit-tsprofit\n        collection=min(ar,max(0.,liquid_sub-2));ar-=collection;liquid_sub-=collection\n        eligible=max(0.,other_profit-max(0.,-ret_sub));ret_sub+=other_profit\n        reserve=min(max(0.,35-res_sub),eligible*.1);res_sub+=reserve;ret_sub-=reserve\n        dividend=max(0.,min(max(0.,other_profit)*.75,max(0.,ret_sub),max(0.,liquid_sub)))\n        ret_sub-=dividend;liquid_sub-=dividend\n        special=0.\n        if n>=12:\n            special=min(max(0.,liquid_sub-2)/max(1,22-n),max(0.,ret_sub),max(0.,liquid_sub))\n            ret_sub-=special;liquid_sub-=special\n        shortfall=max(0.,2-liquid_sub) if run+owned_capacity>0 else max(0.,-liquid_sub)\n        if shortfall:\n            liquid_sub+=shortfall;balances.append(shortfall);amort.append(shortfall/15);starts.append(n+1);ts_loan.append(False)\n        admin=.55 if run+owned_capacity>0 else 0\n        parent_interest=bridge*.027\n        parent_earnings=dividend+special+tsreceipt-capital_back-exit_support-admin-parent_interest\n        liquid_parent+=dividend+special+tsreceipt+collection-construction*.2-admin-parent_interest\n        requested=max(0.,profit-admin-parent_interest)*(.42 if n<=10 else .70)\n        if n>12:requested+=max(0.,liquid_parent-2)/max(1,22-n)\n        shortage=max(0.,-liquid_parent);bridge+=shortage;liquid_parent+=shortage\n        repay=min(bridge,max(0.,liquid_parent-2));bridge-=repay;liquid_parent-=repay\n        eligible=max(0.,parent_earnings-max(0.,-ret_parent));ret_parent+=parent_earnings\n        reserve=min(max(0.,50.498824311*.5-res_parent),eligible*.1)\n        ret_parent-=reserve;res_parent+=reserve\n        distribution=min(requested,max(0.,ret_parent),max(0.,liquid_parent-1))\n        ret_parent-=distribution;liquid_parent-=distribution\n        if n==80:\n            assert abs(fund)<1e-5\n            distribution+=liquid_parent+liquid_sub+tscash+intermediate+interreserve;liquid_parent=liquid_sub=0.\n        payments.append(distribution/50.498824311);cash.append((liquid_parent,liquid_sub))\n        taishan.append(dict(taishan_nopat=tsoperating_profit,taishan_interest_after_tax=tsinterest,taishan_profit=tsprofit,taishan_cash=tscash,taishan_retained=tsret,taishan_shortfall_draw=need,taishan_exit_call=exit_support,taishan_capital_return=capital_back,taishan_debt_closing=sum(b for b,owned in zip(balances,ts_loan) if owned)))\n    return dict(value=sum(x/(1+r)**(i+1) for i,x in enumerate(payments)),\n                terminal=sum(x/(1+r)**(i-4) for i,x in enumerate(payments) if i>=5),\n                dps=payments[:5],cash=cash,taishan=taishan)\n\nchecks={}\noriginal=json.loads(pathlib.Path(__file__).with_name(\'2026-Q3-output.json\').read_text())\nfor name,tariff,normal,r,end,flat in [(\'core_low\',.330,12.4,.085,40,10),(\'tariff_minus_001\',.325,12.7,.08,40,10),(\'shorter_mature_life\',.335,12.7,.08,32,6)]:\n    independent=reconstruct(tariff,normal,r,end,flat);saved=original[\'results\'][name]\n    assert abs(independent[\'value\']-saved[\'value\'])<1e-10\n    assert abs(independent[\'terminal\']-saved[\'terminal_year5\'])<1e-10\n    for i,(a,b) in enumerate(zip(independent[\'dps\'],saved[\'dps\'])):assert abs(a-b)<1e-10\n    for i,(pc,sc) in enumerate(independent[\'cash\']):\n        assert abs(pc-saved[\'rows\'][i][\'parent_cash\'])<1e-8\n        assert abs(sc-saved[\'rows\'][i][\'sub_cash\'])<1e-8\n    for i,row in enumerate(independent[\'taishan\']):\n        for key,value in row.items():assert abs(value-saved[\'rows\'][i][key])<1e-8,(name,i,key,value,saved[\'rows\'][i][key])\n    checks[name]={k:v for k,v in independent.items() if k not in (\'cash\',\'taishan\')}\n    checks[name][\'taishan_80_year_identity_verified\']=True\nprint(json.dumps(dict(passed=True,literal_economic_reconstruction=checks),ensure_ascii=False,sort_keys=True,indent=2))\n', __file__, "exec"), {"__file__":__file__, "__name__":"__main__"})
print(_buffer.getvalue())
exec(compile("from pathlib import Path\nfrom decimal import Decimal as D\nimport json,pathlib,importlib.util,hashlib\nroot=pathlib.Path(__file__).resolve().parent;o=json.loads((root/'2026-Q3-output.json').read_text());b=o['results']['base'];checks=[]\n# Independent literal mature retirement annuities for each of 30 retirement years.\nannual=D(0)\nfor n in range(11,41):\n cost=D(4)/D(30)*D('1.055')**n\n annual+=cost/sum(D('1.02')**(n-k) for k in range(1,n+1))\ndeposit=annual*D('1.785')/D('17.1103056');np=D('.4')*D('.51')+D(25)*D('.027')*D('.75');interest=D(25)*D('.027')*D('.75');profit=np-interest-deposit\nfor key,v in [('taishan_retirement_deposit',deposit),('taishan_nopat',np),('taishan_interest_after_tax',interest),('taishan_profit',profit)]:assert abs(float(v)-b['rows'][0][key])<1e-11;checks.append([key,float(v)])\n# A 2027 100%-owned new Lufeng5 half operating year, no market security price.\nrev=D('1.2')*D('.5')*D(7150)/D(1000)*D('.335');opex=D('1.2')*D('.5')*D(7150)/D(1000)*D('.14');dep=D('20.376')*D('.033')*D('.5');nopat=(rev-opex-dep)*D('.75')\npj=next(x for x in b['rows'][0]['projects'] if x['name']=='陆丰5');assert abs(float(nopat)-pj['nopat'])<1e-12;checks.append(['Lufeng5_nopat',float(nopat)])\n# All source-specific debts, retirement fund, residual liquidation, and actual holder PV.\nsets=list(o['results'].items())+[(name+'_aux',z['full_holder_model'])for name,z in o['independent_unit_method'].items()]\nfor name,v in sets:\n rows=v['rows'];rate=v['parameters']['r'];last=rows[-1];pv=sum(r['dps']/(1+rate)**(i+1) for i,r in enumerate(rows));assert abs(pv-v['value'])<1e-11\n fund=0\n for i,r in enumerate(rows):\n  assert abs(r['interest']-r['taishan_interest_after_tax']-r['other_interest_after_tax'])<1e-10\n  assert abs(r['taishan_interest_gross']-r['taishan_debt_opening']*v['parameters']['rate'])<1e-10\n  fund=fund*1.02+r['decommission_funding']-r['decommission_payment'];assert abs(fund-r['decommission_fund'])<1e-7 and fund>-1e-6\n  if i+1>=v['parameters']['mature_end']:assert r['taishan_debt_closing']<1e-7\n assert abs(fund)<1e-6 and last['debt']<1e-7 and last['parent_bridge']<1e-7\n assert abs(last['parent_cash'])+abs(last['sub_cash'])+abs(last['taishan_cash'])+abs(last['intermediate_cash'])+abs(last['intermediate_reserve'])<1e-7\ns=importlib.util.spec_from_file_location('prod',root/'2026-Q3.py');m=importlib.util.module_from_spec(s);s.loader.exec_module(m)\na=m.legal_step(-5,0,100,4,100,100);b2=m.legal_step(a[0],a[1],100,4,a[2]+4,100);assert a[3]==0 and abs(b2[3]-2.7)<1e-12 and abs(b2[4]-.3)<1e-12\nprint(json.dumps({'independent_decimal':checks,'full_main_and_aux_scenarios_checked':len(sets),'actual_lossfirst_test':[a,b2],'fund_loan_liquidation_PV_checks':'passed'},indent=2))\n", __file__, "exec"), {"__file__":__file__, "__name__":"__main__", "_AUTHOR_JSON":_buffer.getvalue() if _buffer else ""})
